<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import AppIcon from '../components/AppIcon.vue'
import StatusBadge from '../components/StatusBadge.vue'
import RunReport from '../components/RunReport.vue'
import {state,caseName,cancelRun} from '../store'
import {dateTime,statusLabels} from '../uiHelpers'
import {kindLabels,type Kind} from '../types'
const route=useRoute(),status=ref('all'),query=ref(''),kind=ref('all'),environment=ref('all'),period=ref('all'),selected=ref(''),page=ref(1),pageSize=25
const filterKey='testpilot-runs-filters:'+state.projectId
try{const saved=JSON.parse(sessionStorage.getItem(filterKey)||'{}');for(const [field,key] of [[status,'status'],[query,'query'],[kind,'kind'],[environment,'environment'],[period,'period']] as const)field.value=saved[key]||field.value;page.value=saved.page||1}catch{}
function persist(){sessionStorage.setItem(filterKey,JSON.stringify({status:status.value,query:query.value,kind:kind.value,environment:environment.value,period:period.value,page:page.value}))}
watch([status,query,kind,environment,period],()=>{page.value=1;persist()});watch(page,persist)
const runs=computed(()=>state.runs.filter(r=>(status.value==='all'||r.status===status.value)&&(kind.value==='all'||r.kind===kind.value)&&(environment.value==='all'||r.environment===environment.value)&&(period.value==='all'||Date.now()-new Date(r.createdAt).getTime()<Number(period.value)*86400000)&&`${r.id} ${caseName(r.caseId)}`.toLowerCase().includes(query.value.toLowerCase())))
const pageCount=computed(()=>Math.max(1,Math.ceil(runs.value.length/pageSize))),paged=computed(()=>runs.value.slice((page.value-1)*pageSize,page.value*pageSize))
watch(pageCount,count=>page.value=Math.min(page.value,count))
const current=computed(()=>state.runs.find(r=>r.id===(route.params.id||selected.value)))
async function stop(){if(current.value)await cancelRun(current.value.id)}
</script>
<template><div @keydown.esc="selected=''" class="page runs-page"><div class="page-heading"><div><h1>{{route.params.id?'运行报告':'运行记录'}}<span v-if="!route.params.id" class="heading-count">{{state.runs.length}}</span></h1><p>{{route.params.id?'查看执行结果、步骤日志与测试证据。':'追踪每次执行，定位失败并查看测试报告。'}}</p></div><div class="heading-actions"><button v-if="['running','queued'].includes(current?.status??'')" class="button secondary" @click="stop">取消运行</button><RouterLink to="/cases" class="button secondary"><AppIcon name="cases" :size="16"/>选择用例</RouterLink></div></div><RouterLink v-if="route.params.id" to="/runs" class="back-link"><AppIcon name="back" :size="15"/>全部运行</RouterLink>
<template v-if="!route.params.id"><div class="list-toolbar"><label class="search-field"><AppIcon name="search" :size="16"/><input v-model="query" aria-label="搜索运行记录" placeholder="搜索用例或运行编号"/></label><select v-model="kind" class="select" aria-label="筛选运行类型"><option value="all">全部类型</option><option v-for="(label,key) in kindLabels" :key="key" :value="key">{{label}}</option></select><select v-model="status" class="select" aria-label="筛选运行状态"><option value="all">全部状态</option><option v-for="key in ['queued','running','passed','failed','error','timed_out','interrupted','cancelled','completed']" :key="key" :value="key">{{statusLabels[key]}}</option></select><select v-model="environment" class="select" aria-label="筛选运行环境"><option value="all">全部环境</option><option v-for="name in [...new Set(state.runs.map(r=>r.environment))]" :key="name">{{name}}</option></select><select v-model="period" class="select" aria-label="筛选运行时间"><option value="all">全部时间</option><option value="1">最近 24 小时</option><option value="7">最近 7 天</option><option value="30">最近 30 天</option></select></div><div class="runs-workspace" :class="{'has-preview':!!current}"><section class="panel table-panel"><table class="data-table runs-table"><thead><tr><th>用例／运行</th><th>状态</th><th>环境</th><th>耗时</th><th>开始时间</th><th>操作</th></tr></thead><tbody><tr v-for="run in paged" :key="run.id" :class="{selected:current?.id===run.id}"><td><RouterLink :to="'/runs/'+run.id" class="table-case-title">{{caseName(run.caseId)}}</RouterLink><div class="table-secondary">{{run.kind?kindLabels[run.kind as Kind]:''}} · v{{run.revision}}<span class="mono"> · {{run.id.slice(-6)}}</span></div></td><td><StatusBadge :status="run.status"/></td><td>{{run.environment}}</td><td>{{run.duration}}</td><td class="muted">{{dateTime(run.createdAt)}}</td><td><div class="row-actions"><RouterLink :to="'/runs/'+run.id" class="text-button">报告</RouterLink><button class="text-button" @click="selected=selected===run.id?'':run.id">预览</button></div></td></tr></tbody></table><div v-if="!runs.length" class="empty-state"><AppIcon name="search" :size="25"/><h3>没有匹配的记录</h3><button class="text-button" @click="query='';status='all';kind='all';environment='all';period='all'">清除筛选</button></div><div class="table-footer"><span>{{runs.length}} 条 · 每页 {{pageSize}} 条</span><div class="pagination"><button class="icon-button" aria-label="上一页运行" :disabled="page<=1" @click="page--"><AppIcon name="back" :size="16"/></button><span>{{page}} / {{pageCount}}</span><button class="icon-button" aria-label="下一页运行" :disabled="page>=pageCount" @click="page++"><AppIcon name="arrow" :size="16"/></button></div></div></section><div v-if="current" class="preview-backdrop" @click="selected=''"/><aside v-if="current" class="panel run-preview" aria-label="运行报告预览"><div class="preview-heading"><RouterLink :to="'/runs/'+current.id" class="text-button">打开完整报告<AppIcon name="external" :size="15"/></RouterLink><button class="icon-button" aria-label="关闭报告预览" @click="selected=''"><AppIcon name="close" :size="18"/></button></div><RunReport :key="current.id" :run="current"/></aside></div></template>
<section v-else class="panel full-report"><RunReport v-if="current" :key="current.id" :run="current"/><div v-else class="empty-state"><h3>没有找到这条运行记录</h3><RouterLink to="/runs" class="button secondary">返回运行列表</RouterLink></div></section></div></template>
